for old, new, n in pairs:
    c = src.count(old)
    if c != n:
        print("!! 命中 %d 次（期望 %d）：%s" % (c, n, old[:90].replace("\n", "\\n")))
        bad += 1
        continue
    src = src.replace(old, new)
if bad:
    print("有 %d 处未匹配，未写入。已匹配的也未写入。" % bad)
